parts.solution:
public final class Account {
    private final String id;
    private long balanceCents;

    public Account(String id, long openingCents) {
        if (openingCents < 0) throw new IllegalArgumentException("negative opening balance");
        this.id = id;
        this.balanceCents = openingCents;
    }

    public String id() { return id; }

    public synchronized long balance() { return balanceCents; }

    public synchronized void deposit(long cents) {
        requirePositive(cents);
        balanceCents = Math.addExact(balanceCents, cents);
    }

    public synchronized void withdraw(long cents) throws InsufficientFundsException {
        requirePositive(cents);
        if (cents > balanceCents) throw new InsufficientFundsException(id, cents, balanceCents);
        balanceCents -= cents;
    }

    private static void requirePositive(long cents) {
        if (cents <= 0) throw new IllegalArgumentException("amount must be positive: " + cents);
    }
}

public final class Ledger {
    public void transfer(Account from, Account to, long cents) throws InsufficientFundsException {
        if (from == to) throw new IllegalArgumentException("same account");
        Account first = from.id().compareTo(to.id()) < 0 ? from : to;
        Account second = first == from ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.withdraw(cents);
                to.deposit(cents);
            }
        }
    }
}

public record Transfer(UUID id, String fromId, String toId, long cents, Instant at) {}

public final class Ledger {
    private final Clock clock;
    private final List<Transfer> history = new ArrayList<>();

    public Ledger(Clock clock) { this.clock = clock; }

    public void transfer(Account from, Account to, long cents) throws InsufficientFundsException {
        if (from == to) throw new IllegalArgumentException("same account");
        Account first = from.id().compareTo(to.id()) < 0 ? from : to;
        Account second = first == from ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.withdraw(cents);
                to.deposit(cents);
                synchronized (history) {
                    history.add(new Transfer(UUID.randomUUID(), from.id(), to.id(), cents, clock.instant()));
                }
            }
        }
    }

    public List<Transfer> history() {
        synchronized (history) {
            return List.copyOf(history);
        }
    }
}

